#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

struct Matrix {
    long long m[2][2];
    Matrix() {
        memset(m, 0, sizeof m);
    }
    Matrix(long long mat[2][2]) {
        for (int i=0; i<2; i++) {
            for (int j=0; j<2; j++) {
                m[i][j] = mat[i][j];
            }
        }
    }
    Matrix pow(long long p) const {
        Matrix res({{1, 0}, {0, 1}});
        Matrix base = *this;
        while (p > 0) {
            if (p & 1) {
                res = res.multiply(base);
            }
            base = base.multiply(base);
            p >>= 1;
        }
        return res;
    }
    Matrix multiply(const Matrix& m2) const {
        long long r[2][2] = {{0, 0}, {0, 0}};
        for (int i=0; i<2; i++) {
            for (int j=0; j<2; j++) {
                for (int k=0; k<2; k++) {
                    r[i][j] += m[i][k] * m2.m[k][j];
                }
                r[i][j] %= MOD;
            }
        }
        return Matrix(r);
    }
};

long long powMod(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, L, R;
    cin >> n >> m >> L >> R;
    long long length = R - L + 1;

    if (n % 2 == 1 && m % 2 == 1) {
        cout << powMod(length % MOD, n * m) << "\n";
    } else {
        if (length % 2 == 0) {
            long long total = powMod(length % MOD, n * m - 1);
            long long answer = total * (length / 2) % MOD;
            cout << answer << "\n";
        } else {
            long long half = length / 2;
            long long mat[2][2] = {{half, half + 1}, {half + 1, half}};
            Matrix matrix(mat);
            Matrix res = matrix.pow(n * m);
            cout << res.m[0][0] << "\n";
        }
    }
    return 0;
}

